verification_commands.ac1:
set -u
# ac1 - COMMITTED BYTES ARE MACHINE OUTPUT, and the instruments are frozen.
# WRITE fence by design (the t102 ac3 precedent): it backs up the bytes the tree
# carries, regenerates BOTH documents in place, compares the pre-regeneration
# bytes against the fresh generator output (a hand-edited or stale document
# diverges here and REDs), checks the fresh bytes against their HEAD blobs (the
# refresh must be COMMITTED, not left dirty), and RESTORES the original bytes on
# every exit path through the trap, so a failed leg cannot leave the tree
# inconsistent for the fences that run after it. Every comparison is CR-normalised
# because core.autocrlf=true smudges the committed LF blobs to CRLF in the working
# tree (the disclosed t102 ac3 checkout-artifact class); a raw cmp of blob against
# working file would RED on checkout shape, not product.
test -f docs/criteria/agent_pack_verification.md || { echo "ac1 RED: docs/criteria/agent_pack_verification.md missing - run this fence from the repository root"; exit 1; }
test -f docs/criteria/req_coverage_verification.md || { echo "ac1 RED: docs/criteria/req_coverage_verification.md missing - the matrix generator has never run on this tree"; exit 1; }
test -f backend/scripts/agent_pack_verification.py || { echo "ac1 RED: backend/scripts/agent_pack_verification.py missing"; exit 1; }
test -f backend/scripts/req_coverage_verification.py || { echo "ac1 RED: backend/scripts/req_coverage_verification.py missing"; exit 1; }
export PATH="$HOME/.local/bin:$PATH"
command -v uv >/dev/null 2>&1 || { echo "ac1 RED: uv is missing - both generators run under the shared-venv convention (uv run) and a skipped regeneration proves nothing"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac1 RED: python3 is missing"; exit 1; }
AP=docs/criteria/agent_pack_verification.md
MX=docs/criteria/req_coverage_verification.md
export BK
BK=$(mktemp -d) || { echo "ac1 RED: cannot create the backup dir"; exit 1; }
restore() { cp "$BK/ap.md" "$AP" 2>/dev/null; cp "$BK/mx.md" "$MX" 2>/dev/null; rm -rf "$BK" 2>/dev/null; }
trap restore EXIT
cp "$AP" "$BK/ap.md" || { echo "ac1 RED: cannot back up the agent-pack document"; exit 1; }
cp "$MX" "$BK/mx.md" || { echo "ac1 RED: cannot back up the matrix"; exit 1; }
COL=$(mktemp) || { echo "ac1 RED: cannot create the collection capture"; exit 1; }
LSF=$(mktemp) || { echo "ac1 RED: cannot create the symlink capture"; exit 1; }
( cd backend && uv run pytest --collect-only -q 2>/dev/null | tr -d "\r" > "$COL" ) || { echo "ac1 RED: the backend collection capture failed - the agent-pack generator takes its collection count from a capture file and refuses an empty one"; rm -f "$COL" "$LSF"; exit 1; }
[ -s "$COL" ] || { echo "ac1 RED: the collection capture is empty"; rm -f "$COL" "$LSF"; exit 1; }
G=$(wslpath -w "$PWD")
# The generator parses the 120000 symlink modes. WSL git carries them on this
# checkout, but the documented t94-family hazard is that a Windows checkout can
# report them as 100644, so the capture is taken through whichever git actually
# delivers symlink modes: WSL git first, cmd.exe git as the fallback (cmd.exe
# cannot reach a WSL-native UNC path, so it is the fallback and not the primary).
cmd.exe /d /c "git -C $G ls-files -s .agents" 2>/dev/null | tr -d "\r" > "$LSF"
if ! grep -q '^120000 ' "$LSF" 2>/dev/null; then
  git ls-files -s .agents 2>/dev/null | tr -d "\r" > "$LSF"
fi
[ "$(grep -c '^120000 ' "$LSF" 2>/dev/null)" -ge 1 ] || { echo "ac1 RED: neither cmd.exe git nor WSL git reports the .agents rows with 120000 symlink modes - the agent-pack generator's symlink check has no input, which is a checkout-shape class to disclose, not a product failure to hide"; rm -f "$COL" "$LSF"; exit 1; }
( cd backend && PYTHONPATH=. uv run python scripts/agent_pack_verification.py --collection-file "$COL" --ls-files-file "$LSF" >/dev/null 2>&1 ) || { echo "ac1 RED: the agent-pack generator exits nonzero on this tree, so its committed evidence cannot be regenerated at all"; rm -f "$COL" "$LSF"; exit 1; }
# The matrix generator is stdlib-only and root-discovering, so python3 calls it
# directly; the agent-pack generator needs the venv because its collection capture
# comes from pytest.
python3 backend/scripts/req_coverage_verification.py >/dev/null 2>&1 || { echo "ac1 RED: the matrix generator exits nonzero - the fail-closed fence means the tree carries GAP or unpointed rows, which no refresh may paper over"; rm -f "$COL" "$LSF"; exit 1; }
rm -f "$COL" "$LSF"
python3 - <<'PYAC1' || exit 1
import hashlib, os, subprocess, sys
def fail(m):
    sys.stderr.write("ac1 RED: " + m + "\n"); raise SystemExit(1)
KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
        "GIT_COMMON_DIR", "GIT_PREFIX")
env = {k: v for k, v in os.environ.items() if k not in KEYS}
def cr(b):
    return b.replace(b"\r\n", b"\n")
def git(args):
    p = subprocess.run(["git"] + args, capture_output=True, env=env)
    return cr(p.stdout or b""), (p.stderr or b"").decode("utf-8", "replace")
def blob(rev_, path):
    out, err = git(["show", "%s:%s" % (rev_, path)])
    if not out:
        w = subprocess.run(["wslpath", "-w", os.getcwd()], capture_output=True,
                           text=True, env=env).stdout.strip().replace("\r\n", "\n")
        out, err = git(["cmd.exe", "/d", "/c", "git -C %s show %s:%s" % (w, rev_, path)])
    if not out:
        fail("blob %s:%s is unreadable through WSL git AND cmd.exe git (%s)" % (rev_, path, err[:120]))
    return out
PAIRS = [("docs/criteria/agent_pack_verification.md", "backend/scripts/agent_pack_verification.py", "ap.md"),
         ("docs/criteria/req_coverage_verification.md", "backend/scripts/req_coverage_verification.py", "mx.md")]
import os as _os
for doc, gen, bkname in PAIRS:
    pre = cr(open(_os.environ["BK"] + "/" + bkname, "rb").read())   # bytes BEFORE regeneration
    fresh = cr(open(doc, "rb").read())                              # bytes the generator just wrote
    if pre != fresh:
        fail("%s is NOT machine output on this tree: the bytes the tree carried before regeneration hash %s but a fresh run of %s leaves %s, and the first differing line is %s - a hand-edited or stale document is exactly what this card exists to replace, and regeneration must be the ONLY writer"
             % (doc, hashlib.sha256(pre).hexdigest()[:12], gen, hashlib.sha256(fresh).hexdigest()[:12],
                next((l1[:70] for l1, l2 in zip(pre.decode("utf-8", "replace").split("\n"),
                                                fresh.decode("utf-8", "replace").split("\n")) if l1 != l2), "(length differs)")))
    head = cr(blob("HEAD", doc))
    if head != fresh:
        fail("%s is machine output but NOT what HEAD carries (HEAD blob %s vs fresh generator output %s) - the refresh must be COMMITTED on the branch, not left in the working tree, because the committed evidence is the deliverable"
             % (doc, hashlib.sha256(head).hexdigest()[:12], hashlib.sha256(fresh).hexdigest()[:12]))
    print("ac1 evidence: %s reproduces from %s byte-identically AND equals its HEAD blob (CR-normalised, sha %s)" % (doc, gen, hashlib.sha256(fresh).hexdigest()[:12]))
    gwork = cr(open(gen, "rb").read())
    ghead = cr(blob("HEAD", gen))
    if ghead != gwork:
        fail("%s differs from its HEAD blob - the generators are FROZEN for this card; the drift this card fixes is evidence drift, never instrument drift" % gen)
    print("ac1 evidence: %s is byte-identical to its HEAD blob (frozen instrument)" % gen)
print("ac1 GREEN: MACHINE OUTPUT AND FROZEN INSTRUMENTS - both owned documents equal a fresh run of their own generator on this tree and equal their HEAD blobs, and both generators are untouched")
PYAC1

verification_commands.ac2:
