# The fence DERIVES the count itself (pytest --collect-only capture, `::` count)
# and then requires the document's BACKEND_COLLECTION row, its floor and its
# METHOD prose count to equal that derived number. Nothing here quotes 270 or
# 303: a document that still attests the t35-era count on a tree that collects
# more REDs by construction, and so does a document whose prose and token rows
# disagree with each other.
test -f docs/criteria/agent_pack_verification.md || { echo "ac2 RED: docs/criteria/agent_pack_verification.md missing - run this fence from the repository root"; exit 1; }
export PATH="$HOME/.local/bin:$PATH"
command -v uv >/dev/null 2>&1 || { echo "ac2 RED: uv is missing - the collection count cannot be derived"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac2 RED: python3 is missing"; exit 1; }
