( cd backend && uv run pytest --collect-only -q 2>/dev/null | tr -d "\r" > "$COL" ) || { echo "ac2 RED: the backend collection capture failed"; rm -f "$COL"; exit 1; }
[ -s "$COL" ] || { echo "ac2 RED: the collection capture is empty"; rm -f "$COL"; exit 1; }
python3 - "$COL" <<'PYAC2' || { rm -f "$COL"; exit 1; }
import os, re, sys
cap = sys.argv[1]
def fail(m):
    sys.stderr.write("ac2 RED: " + m + "\n"); raise SystemExit(1)
try:
    os.unlink(cap + ".keep")
except OSError:
    pass
derived = sum(1 for line in open(cap, encoding="utf-8", errors="replace") if "::" in line)
if derived < 1:
    fail("the collection capture names zero node ids")
