if said != derived:
    fail("the committed document attests BACKEND_COLLECTION %d while this tree collects %d - the evidence is stale by exactly the drift this card exists to remove (the count is derived here, so no future test addition can be quoted past it)" % (said, derived))
if floor > derived:
    fail("the document's own floor %d exceeds the derived count %d - a floor above the collection is a fence that can never re-run GREEN" % (floor, derived))
prose = re.search(r"(?m)^METHOD collection (\d+) nodes \(floor (\d+)\)", doc)
