    fail("the METHOD prose count line is not in the shape the generator writes - the document was hand-edited rather than regenerated")
if int(prose.group(1)) != derived:
    fail("the METHOD prose says %s nodes while the derived count is %d - prose and token row must move together, which is what regeneration guarantees and hand-editing does not" % (prose.group(1), derived))
footer = re.search(r"(?m)^ALL_CHECKS_PASS (\d+) PASS$", doc)
if not footer:
    fail("the document does not end in its ALL_CHECKS_PASS <n> PASS footer - the generator's terminal line is missing, so the report is not a completed run")
if int(footer.group(1)) < 18:
    fail("the footer carries %s PASS rows, below the t28 precedent scale of 18 - rows were removed rather than refreshed" % footer.group(1))
print("ac2 evidence: METHOD prose count %d == derived count; footer ALL_CHECKS_PASS %s PASS" % (derived, footer.group(1)))
print("ac2 GREEN: THE DOCUMENT IS CURRENT - BACKEND_COLLECTION, its floor, the METHOD prose count and the footer all agree with a count derived live in this fence (%d), so the t35-era 270 cannot survive here" % derived)
