echo "ac3 evidence: two consecutive generator runs are byte-identical (sha $(sha256sum "$R1" | cut -c1-12))"
rm -f "$R1" "$R2"
python3 - <<'PYAC3' || exit 1
import hashlib, re, sys
MX = "docs/criteria/req_coverage_verification.md"
def fail(m):
    sys.stderr.write("ac3 RED: " + m + "\n"); raise SystemExit(1)
def cr(b):
    return b.replace(b"\r\n", b"\n")
run1 = cr(open(MX, "rb").read())
