    fail("the matrix is empty after two generator runs")
print("ac3 evidence: regenerated matrix sha (CR-normalised) = %s, %d lines" % (hashlib.sha256(run1).hexdigest()[:12], run1.count(b"\n") + 1))
text = run1.decode("utf-8", "replace")
rows = re.findall(r"(?m)^REQ_ROW PASS id=(REQ-[A-Z_]+-[0-9]{3}) family=(\w+) status=(\w+) method=(\S+) pointers=(\S+)", text)
if not rows:
    fail("no REQ_ROW PASS lines parse out of the matrix - the row grammar the generator writes has changed, so the self-consistency check has no footing")
ids = [r[0] for r in rows]
if len(set(ids)) != len(ids):
    fail("%d REQ_ROW lines but only %d unique ids - a duplicated row is not an enumeration" % (len(ids), len(set(ids))))
statuses = {}
for _, _, st, _, ptr in rows:
    statuses[st] = statuses.get(st, 0) + 1
unpointed = [i for i, (_, _, st, _, ptr) in zip(ids, rows) if st != "GAP" and (not ptr or ptr == "-")]
if unpointed:
    fail("%d non-GAP rows carry no evidence pointer (first %s) - the fail-closed contract says the generator would have exited nonzero, so this document is not its output" % (len(unpointed), unpointed[0]))
matrix_line = re.search(r"(?m)^REQ_MATRIX PASS rows=(\d+) unique=(\d+) idset=sha256:([0-9a-f]{8,})(?: PASS)?$", text)
if not matrix_line:
    fail("the REQ_MATRIX summary line is not in the generator's shape - a hand-edited summary is exactly what self-consistency catches")
said_rows, said_unique = int(matrix_line.group(1)), int(matrix_line.group(2))
if said_rows != len(rows) or said_unique != len(set(ids)):
    fail("the summary line claims rows=%d unique=%d while the document's own REQ_ROW lines number %d/%d - the summary was written, not derived" % (said_rows, said_unique, len(rows), len(set(ids))))
print("ac3 evidence: summary rows/unique %d/%d equals the counts derived from the document's own REQ_ROW lines" % (said_rows, said_unique))
tally = dict((m.group(1), int(m.group(2))) for m in re.finditer(r"(?m)^REQ_STATUS_COUNT (\w+) (\d+)$", text))
unknown = sorted(k for k in set(tally) - set(statuses) if tally[k] != 0)
if unknown:
    fail("the tally prints non-zero statuses %s that no row carries - the summary was written, not derived (a status printed at zero with no rows is the legitimate closed-vocabulary shape)" % unknown)
mismatched = {k: (tally[k], statuses.get(k, 0)) for k in tally if tally[k] != statuses.get(k, 0)}
if mismatched:
    fail("the printed status tally disagrees with the tally derived from the rows for %s (printed vs derived) - re-labelled or deleted rows are caught here, not by a quoted constant"
         % ", ".join("%s=%s/%s" % (k, v[0], v[1]) for k, v in sorted(mismatched.items())))
missing_status = sorted(set(statuses) - set(tally))
if missing_status:
    fail("rows carry statuses %s that the printed tally never declares" % missing_status)
gap = tally.get("GAP", -1)
if gap != 0:
    fail("the matrix carries GAP=%d rows - the fail-closed fence means the generator would exit nonzero, so a GREEN here is impossible" % gap)
print("ac3 evidence: status tally DERIVED from the rows equals the printed tally (%s), GAP=0, unpointed non-GAP rows=0" % ", ".join("%s=%d" % kv for kv in sorted(tally.items())))
fams = dict((m.group(1), int(m.group(2))) for m in re.finditer(r"(?m)^REQ_FAMILY PASS family=(\w+) rows=(\d+)$", text))
derived_fam = {}
for _, fam_name, _, _, _ in rows:
    derived_fam[fam_name] = derived_fam.get(fam_name, 0) + 1
if fams != derived_fam:
    fail("the printed family table %s does not equal the family counts derived from the rows %s" % (sorted(fams.items())[:6], sorted(derived_fam.items())[:6]))
families_line = re.search(r"(?m)^REQ_FAMILIES PASS total=(\d+) distinct=(\d+)$", text)
if not families_line or int(families_line.group(1)) != len(rows) or int(families_line.group(2)) != len(fams):
    fail("the REQ_FAMILIES line does not close at the derived row count and family count")
print("ac3 evidence: family table closes at %d rows across %d families, all derived from the rows themselves" % (len(rows), len(fams)))
if not re.search(r"(?m)^REQ_FENCE PASS gate=fail-closed", text):
    fail("the fail-closed fence declaration vanished from the report - the instrument was edited, not satisfied")
print("ac3 GREEN: SELF-CONSISTENT AND FAIL-CLOSED GREEN - the generator exits 0 twice on byte-identical bytes, and the row count, unique-id count, status tally, family table and footer all equal values DERIVED from the document's own rows (rows=%d, families=%d, GAP=0, unpointed=0)" % (len(rows), len(fams)))
