verification_commands.ac4:
set -u
# ac4 - STORED-LEG HAZARD, DERIVED AND REPLAYED. merge_test_index.json is
# ORCHESTRATOR-OWNED and read-only here: this fence PARSES it, selects the legs
# that name either owned document, resolves each stored command's OWN operand
# binding (the t35 legs grep "$d" bound to the path; the t57/t58 legs capture the
# bytes into $C/$RC and pipe them), extracts the anchored literal grep patterns
# whose operand is that document, and requires every one of them to be satisfied
# by the bytes this card ships. The pattern count is DERIVED, never quoted, so a
# future leg that greps these documents joins the check without any edit to this
# card. Groom ran the same scanner two ways to prove it bites: on the current
# committed documents every pattern is satisfied, and on two mutated copies
# (DEFERRAL_REGISTER 3 -> 4, vocabulary= -> vocab=) it names legs 156 and
# {217,218} respectively. Read-only: nothing is written.
test -f docs/state/merge_test_index.json || { echo "ac4 RED: docs/state/merge_test_index.json missing - the hazard cannot be derived without the shipped index"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac4 RED: python3 is missing - this fence's validator is python3 by contract, with no skip path, because a skipped hazard check proves nothing"; exit 1; }
python3 - <<'PYAC4' || exit 1
import json, os, re, sys
OWNED = ["docs/criteria/agent_pack_verification.md", "docs/criteria/req_coverage_verification.md"]
POSIX = {"[[:space:]]": "[ \t]", "[[:alpha:]]": "[A-Za-z]", "[[:digit:]]": "[0-9]",
         "[[:upper:]]": "[A-Z]", "[[:lower:]]": "[a-z]"}
def fail(m):
    sys.stderr.write("ac4 RED: " + m + "\n"); raise SystemExit(1)
def to_py(p):
    p = p.replace('\\"', '"')
    for k, v in POSIX.items():
        p = p.replace(k, v)
    return p
def aliases(cmd, path):
    """variables in THIS stored command that hold the doc's path or its bytes."""
    al = set()
    changed = True
    while changed:
        changed = False
        for m in re.finditer(r"\b([A-Za-z_][A-Za-z0-9_]*)=(\$\([^)]*\)|\"[^\"]*\"|[^;|&\n]*)", cmd):
            var, rhs = m.group(1), m.group(2)
            if var in al:
                continue
            if re.search(r"(^|[^A-Za-z0-9_])" + re.escape(path) + r"([^A-Za-z0-9_]|$)", rhs):
                al.add(var); changed = True; continue
            for a in list(al):
                if re.search(r"(^|[^A-Za-z0-9_])" + re.escape(a) + r"([^A-Za-z0-9_]|$)", rhs):
                    al.add(var); changed = True; break
    return al
def patterns(cmd, path, al):
    """anchored literal patterns whose operand is the doc, a path alias, or a
    capture derived from it (the printf-pipe form)."""
    out = []
    for m in re.finditer(r"grep\s+(?:-[A-Za-z]+\s+)*-qE?\s+\"((?:[^\"\\]|\\.)*)\"", cmd):
        pat = to_py(m.group(1))
        if not (pat.startswith("^") and pat.endswith("$")):
            continue
        body = pat[1:-1]
        if "$" in body.replace("\\$", "").replace("\\.", "."):
            continue  # variable-interpolated pattern: not a literal we can replay
        tail = cmd[m.end():m.end() + 40].strip()
        operand = tail.split()[0] if tail else ""
        name = operand.strip('"').lstrip("$")
        if name in al or re.search(re.escape(path), operand):
            out.append(pat); continue
        head = cmd[max(0, m.start() - 200):m.start()]
        pm = re.search(r"printf[^\|]*\|\s*$", head)
        if pm:
            seg = pm.group(0)
            if re.search(re.escape(path), seg) or any(("$" + a) in seg for a in al):
                out.append(pat)
    return out
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))
legs = idx["tests"]
print("ac4 evidence: index carries %d stored legs (count derived from the shipped file)" % len(legs))
total = 0
broken = []
for path in OWNED:
    if not os.path.isfile(path):
        fail("%s is missing from the tree - the hazard cannot be replayed against a document that is not there" % path)
    doc = open(path, encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
    lines = doc.split("\n")
    named = 0
    hits = 0
    for i, leg in enumerate(legs):
        cmd = leg.get("command", "") or ""
        if path not in cmd:
            continue
        named += 1
        for pat in patterns(cmd, path, aliases(cmd, path)):
            hits += 1
            if not any(re.search(pat, line) for line in lines):
                broken.append((i, leg.get("issue_id"), path, pat[:90]))
    total += hits
    print("ac4 evidence: %s is named by %d stored legs; %d anchored literal patterns resolve to it through their own operand binding and all were replayed against the shipped bytes" % (path, named, hits))
if total < 1:
    fail("zero anchored patterns were derived across both owned documents - the scanner lost its footing (an index whose legs grep nothing is not this tree's index), and a hazard check that checks nothing is a relaxation, not a check")
if broken:
    fail("%d stored pattern(s) break against the bytes this card ships: %s - the index is ORCHESTRATOR-OWNED and this card must NOT patch it: stop, ship the finding as a recorded amendment (the t96/t99 coordinated-amendment precedent) and let the orchestrator re-premise the leg"
         % (len(broken), "; ".join("leg %d (%s) %s pattern %s" % (i, iss, p, pat) for i, iss, p, pat in broken[:6])))
print("ac4 GREEN: HAZARD DERIVED AND CLEAR - %d anchored stored patterns naming the two owned documents all replay GREEN against the shipped bytes, with the leg list and pattern count derived from docs/state/merge_test_index.json at run time" % total)
PYAC4

verification_commands.ac5:
set -u
